    op = observation.get("opponent_position", None) if isinstance(observation, dict) else None
    resources = observation.get("resources", []) if isinstance(observation, dict) else []
    obstacles = observation.get("obstacles", []) if isinstance(observation, dict) else []
    my_path = observation.get("self_path", []) if isinstance(observation, dict) else []
    op_path = observation.get("opponent_path", []) if isinstance(observation, dict) else []

    def p(v):
        if isinstance(v, dict):
            if "x" in v and "y" in v:
                return [v["x"], v["y"]]
            for k in ("position", "pos", "loc", "location"):
                if k in v:
                    r = p(v[k])
                    if r is not None:
                        return r
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            a, b = v[0], v[1]
            if isinstance(a, (int, float)) and isinstance(b, (int, float)):
                return [int(a), int(b)]
        return None

    def occ(x, y):
        for it in obstacles:
            q = p(it)
            if q and q[0] == x and q[1] == y:
                return True
        return False

    def best_target(items):
        best = None
        bd = 10**9
        for it in items:
            q = p(it)
            if q is None:
                continue
            d = abs(q[0] - me[0]) + abs(q[1] - me[1])
            if d < bd:
                bd = d
                best = q
        return best

    tgt = best_target(resources)
    if tgt is None and op is not None:
        tgt = [op[0], op[1]]

    moves = [[0, 0], [1, 0], [-1, 0], [0, 1], [0, -1]]
    best_move = [0, 0]
    best_score = -10**9
    for dx, dy in moves:
        x, y = me[0] + dx, me[1] + dy
        if x < 0 or y < 0 or (w and x >= w) or (h and y >= h) or occ(x, y):
            continue
        score = 0
        if tgt is not None:
            score -= abs(tgt[0] - x) + abs(tgt[1] - y)
        score += (x - me[0]) * 0.1 + (y - me[1]) * 0.1
        if op is not None:
            score += abs(op[0] - x) + abs(op[1] - y) * 0.01
        if [x, y] in my_path:
            score -= 1
        if [x, y] in op_path:
            score -= 0.5
        if score > best_score:
            best_score = score
            best_move = [dx, dy]
    return best_move

